xml.Script:
        Colors[0] := 'C80000'; // Red
        Colors[1] := '4B0082'; // Indigo
        Colors[2] := '006400'; // DarkGreen
        Colors[3] := 'FF7F50'; // Coral
        Colors[4] := '800000'; // Brown
        Colors[5] := '0000C8'; // Blue
        Colors[6] := '009600'; // Green
        Colors[7] := 'FF800A'; // Orange
        clYellow  := 'FFFF00';
        clWhite   := 'FFFFFF';

        R := 0.5;
        H := R;

        NColors := 8;
        NLayers := 11;
        NSegPerColor := 5;

        WD := R * sin(Pi / NColors) * 2 / NSegPerColor;

        N := NColors * NSegPerColor;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i - Pi / NColors);
            y[i] := R * sin(2 * Pi / N * i - Pi / NColors);
        end;

        // layers have different thickness!
        for i := 0 to NLayers - 2 do
          D[i] := x[(NSegPerColor * 3 + 1) / 2 + i];

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
